package com.abhiai.abhiai_backend.controller;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.abhiai.abhiai_backend.dto.moderation.ModerationActionRequest;import com.abhiai.abhiai_backend.security.JwtPrincipal;import com.abhiai.abhiai_backend.service.ModerationService;import jakarta.validation.Valid;@RestController@RequestMapping("/api/v1/admin/moderation")public class ModerationController{private final ModerationService s;public ModerationController(ModerationService s){this.s=s;}@PostMapping("/actions")@ResponseStatus(HttpStatus.NO_CONTENT)public void act(@AuthenticationPrincipal JwtPrincipal p,@Valid@RequestBody ModerationActionRequest r){s.execute(p.email(),r);}}
